import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.TreeSet;

public class BookEntryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static int sign(int n) {
        return Integer.compare(n, 0);
    }

    static List<BookEntry> shelf() {
        List<BookEntry> books = new ArrayList<>();
        books.add(new BookEntry("Dune", 1965));
        books.add(new BookEntry("Emma", 1815));
        books.add(new BookEntry("Anathem", 2008));
        books.add(new BookEntry("dune", 2021));
        books.add(new BookEntry("Solaris", 1961));
        return books;
    }

    public static void main(String[] args) {
        try {
            check("toString", "Dune (1965)", new BookEntry("Dune", 1965).toString());

            check("same title ignoring case compares equal",
                    0, sign(new BookEntry("dune", 2021).compareTo(new BookEntry("Dune", 1965))));
            check("Anathem before Dune", -1,
                    sign(new BookEntry("Anathem", 2008).compareTo(new BookEntry("Dune", 1965))));
            check("Solaris after Emma", 1,
                    sign(new BookEntry("Solaris", 1961).compareTo(new BookEntry("Emma", 1815))));

            List<BookEntry> natural = shelf();
            Collections.sort(natural);
            check("natural sort is by title",
                    "[Anathem (2008), Dune (1965), dune (2021), Emma (1815), Solaris (1961)]",
                    natural.toString());

            List<BookEntry> byYear = shelf();
            byYear.sort(BookEntry.BY_YEAR_THEN_TITLE);
            check("comparator sort is by year",
                    "[Emma (1815), Solaris (1961), Dune (1965), Anathem (2008), dune (2021)]",
                    byYear.toString());

            TreeSet<BookEntry> set = new TreeSet<>(shelf());
            check("TreeSet drops the title duplicate", 4, set.size());
            check("TreeSet keeps the first Dune inserted",
                    "[Anathem (2008), Dune (1965), Emma (1815), Solaris (1961)]",
                    set.toString());

            TreeSet<BookEntry> byYearSet = new TreeSet<>(BookEntry.BY_YEAR_THEN_TITLE);
            byYearSet.addAll(shelf());
            check("with the comparator nothing is dropped", 5, byYearSet.size());
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

