import java.util.Comparator;

public class BookEntry implements Comparable<BookEntry> {

    private final String title;
    private final int year;

    public BookEntry(String title, int year) {
        this.title = title;
        this.year = year;
    }

    public String getTitle() {
        return title;
    }

    public int getYear() {
        return year;
    }

    /** Year ascending, then title ascending ignoring case. */
    public static final Comparator<BookEntry> BY_YEAR_THEN_TITLE =
            Comparator.comparingInt(BookEntry::getYear)
                    .thenComparing(BookEntry::getTitle, String.CASE_INSENSITIVE_ORDER);

    @Override
    public int compareTo(BookEntry other) {
        return title.compareToIgnoreCase(other.title);
    }

    @Override
    public String toString() {
        return title + " (" + year + ")";
    }
}
